begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1726 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_c0a20bc76968c397df5b520f6cd21eb1' and md5(to_jsonb(t)::text)='7d5f5d6a188cefedf3fc0460d29c92f5')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_c0a20bc76968c397df5b520f6cd21eb1';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1f6ade25871e7370$"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte."$text_1f6ade25871e7370$::jsonb,true),'{features}',$text_d04fcefb0f1fc219$[{"id":"mage-armor","kind":"other","name":"Armadura de mago","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte.\n\nAl gastar la última carga: tirar 1d20; con un 1 la varita se destruye. Conservar este procedimiento junto al lanzamiento.\n\nDuración: 8 horas.\n\nCoste: 1 cargas.","showInActions":false}]$text_d04fcefb0f1fc219$::jsonb,true),'{rules,definition,description}',$text_47a68dad3bab2250$[{"id":"campaign-text-0","text":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_47a68dad3bab2250$::jsonb,true),'{rules,personalDescription}',$text_feeda7894407784e$"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro <u>Armadura de mago</u> sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera <u>1d6+1</u> cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes <u>un 1 en un d20</u>, la varita colapsa y se desintegra en polvo inerte."$text_feeda7894407784e$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_c0a20bc76968c397df5b520f6cd21eb1';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_e5cbf01d9f6c577a71250d86bc8f0ea5' and md5(to_jsonb(t)::text)='7258204ae0a21641f4c28ae3eeb071e3')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_e5cbf01d9f6c577a71250d86bc8f0ea5';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_a1570cd70d2f5f70$"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos."$text_a1570cd70d2f5f70$::jsonb,true),'{features}',$text_af3cf1a757f09185$[{"id":"reserve-crystal","kind":"other","name":"Reserva arcana y descarga","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos.\n\nTres opciones de gasto 1/2/3; registrar por separado la corrupción MC, la ventana de 10 minutos, identificación, destrucción y uso en mecanismos. No sustituir la descarga por un conjuro oficial ni descartar sus costes de campaña.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_af3cf1a757f09185$::jsonb,true),'{rules,definition,description}',$text_5b8325390af9ea64$[{"id":"campaign-text-0","text":"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_5b8325390af9ea64$::jsonb,true),'{rules,personalDescription}',$text_ab91e77706d4cd95$"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\n<strong>Mecánica</strong>\n<strong>Cargas:</strong> 3. Recupera <u>1d3</u> cargas al amanecer.\n\n<strong>Usos</strong>\n• <strong>1 carga:</strong> lanzar un conjuro de <u>1.er nivel</u> sin gastar ranura.\n• <strong>2 cargas:</strong> lanzar un conjuro de <u>2.º nivel</u> sin gastar ranura.\n• <strong>3 cargas:</strong> descarga equivalente a <em>Rayo abrasador</em> (3 rayos de <u>2d6</u> de daño de fuego).\n\n<strong>Corruptibilidad</strong>\n• <u>+1 MC</u> por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: <u>+2 MC</u>.\n\n<strong>Identificación</strong>\n<em>Arcana CD 16</em>.\n\n<strong>Destrucción</strong>\nRomperlo con más de <u>30 puntos de daño contundente</u> lo neutraliza, liberando <u>4d6</u> de energía elemental (<em>CON CD 15, mitad con éxito</em>).\n\n<strong>Uso en mecanismos</strong>\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos."$text_ab91e77706d4cd95$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_e5cbf01d9f6c577a71250d86bc8f0ea5';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_21fb3cc0fb7587b505d72707c35e468c' and md5(to_jsonb(t)::text)='bb93e311ae83f86a6a355555f50fb823')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_21fb3cc0fb7587b505d72707c35e468c';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f3ae9b4fecfd8020$"Objeto · Precio base · Peso\nCantimplora · 2 pp · 5 lb (llena)\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f3ae9b4fecfd8020$::jsonb,true),'{rules,definition,description}',$text_0ad7a883d022e3a3$[{"id":"official-table","rows":[["Cantimplora","2 pp","5 lb (llena)"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_0ad7a883d022e3a3$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_21fb3cc0fb7587b505d72707c35e468c';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_2565137d4e08b3c8b7c7722b25c2d079' and md5(to_jsonb(t)::text)='df795418e4286854a430a0a45a9654af')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_2565137d4e08b3c8b7c7722b25c2d079';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_c667310c3c3c17d7$"Objeto · Precio base · Peso\nUtensilios de cocina · 2 pp · 1 lb\n\nUtensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_c667310c3c3c17d7$::jsonb,true),'{features}',$text_17df154811e76464$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Utensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_17df154811e76464$::jsonb,true),'{rules,definition,description}',$text_d91a6351d35012ce$[{"id":"official-table","rows":[["Utensilios de cocina","2 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Utensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_d91a6351d35012ce$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_2565137d4e08b3c8b7c7722b25c2d079';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_313ed8fa89e6b9a86a2a5243b27953b5' and md5(to_jsonb(t)::text)='9d007acde470d81ca9cf53c3c63e2274')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_313ed8fa89e6b9a86a2a5243b27953b5';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_346ce798f07d5474$"Objeto · Precio base · Peso\nCuerda de cáñamo (50 pies) · 1 po · 10 lb\n\nCuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_346ce798f07d5474$::jsonb,true),'{features}',$text_be24ea40c71d093b$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_be24ea40c71d093b$::jsonb,true),'{rules,definition,description}',$text_8cedde3dc4b4e343$[{"id":"official-table","rows":[["Cuerda de cáñamo (50 pies)","1 po","10 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_8cedde3dc4b4e343$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_313ed8fa89e6b9a86a2a5243b27953b5';
