if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_3291b2c39524476b818bd6c416a3aba7' and md5(to_jsonb(t)::text)='5bebc5d75937bd895fdd63528ff696d6')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_3291b2c39524476b818bd6c416a3aba7';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_13c2783a0f6c5ecf$"Objeto · Precio base · Peso\nAmuleto · 5 po · 1 lb\n\nSímbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_13c2783a0f6c5ecf$::jsonb,true),'{features}',$text_20d6da3fc6e17a06$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_20d6da3fc6e17a06$::jsonb,true),'{rules,definition,description}',$text_a2a80e2fdb6b3797$[{"id":"official-table","rows":[["Amuleto","5 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_a2a80e2fdb6b3797$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_arr