if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_ebb896618eca067fb9bbe3dab7a2d60d' and md5(to_jsonb(t)::text)='dc41d52e124c34e0cacc19c5d412ee00')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_ebb896618eca067fb9bbe3dab7a2d60d';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_f90f6a78613d875c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes a un infernal o muerto viviente con esta arma mágica, esa criatura recibirá 2d6 de daño radiante adicional. Si al objetivo le quedan 25 puntos de golpe o menos tras sufrir este daño, deberá superar una tirada de salvación de Sabiduría con CD 15 o será destruido. Si la supera, la criatura quedará asustada de ti hasta el final de tu siguiente turno.\n\nMientras empuñes esta arma, emitirá luz brillante en un radio de 6 m y luz tenue 6 m más allá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f90f6a78613d875c$::jsonb,true),'{rules,personalDescription}',$text_d26e14df57c76560$"Cuando golpeas a un Demonio o a un No Muerto con esta arma mágica, esa criatura recibe 2d6 puntos de daño Radiante adicionales. Si el objetivo tiene 25 Puntos de Golpe o menos después de recibir este daño, debe superar una tirada de salvación de Sabiduría CD 15 o será destruido. Si la tirada de salvación tiene éxito, la criatura tiene el estado de Asustado hasta el final de tu siguiente turno.\n\nLuz. Mientras sostienes esta arma, emite Luz brillante en un radio de 20 pies y Luz tenue en otros 20 pies. La competencia con una maza te permite sumar tu bonificación por competencia a la tirada de ataque de cualquier ataque que realices con ella."$text_d26e14df57c76560$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_ebb896618eca067fb9bbe3dab7a2d60d';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_058c8377210e8115cf71478a1d2b8199' and md5(to_jsonb(t)::text)='a4f488a6a2e062fcb820aa1185ad98ce')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_058c8377210e8115cf71478a1d2b8199';end if;update public.campaign_state_fragments set payload=jsonb_set(payload,'{features}',$text_9ad7b9db04c41b3a$[{"id":"mundane-rule","kind":"other","name":"Uso del equipo","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles para disfrazarse. Esta bolsa con productos de maquillaje, tinte para el pelo y pequeños accesorios te ayuda a disfrazarte y cambiar así tu apariencia. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica para crear un disfraz que engañe a la vista.\n\nResolver las reglas descritas y sus condiciones en la mesa.\n\nDuración: Según la regla..","showInActions":false}]$text_9ad7b9db04c41b3a$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_058c8377210e8115cf71478a1d2b8199';
