}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_75839275c094535772a5c065a209240b';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_82f14c91203dcc025daebf305240e124' and md5(to_jsonb(t)::text)='d997056aa7eee975fe06f7f1a4dcd177')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_82f14c91203dcc025daebf305240e124';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_7d0ad9435aca71d9$"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."$text_7d0ad9435aca71d9$::jsonb,true),'{rules,definition,description}',$text_858a5902d36eada8$[{"id":"original-text-0","text":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.","type":"paragraph","section":"description","sourceIds":["original:cb6ee5a619b222ffe82fbe5dc106180a8e11292b94d8b51402f4983dc92a0803"],"provenance":"unreviewed"}]$text_858a5902d36eada8$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_3cb6b459471edb7b$["original-text-0"]$text_3cb6b459471edb7b$::jsonb?id),jsonb_build_array('original-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6