sion}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_ab29f134c3a433df9f3748bb0f74ffbd';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_df0f0d60fa767a43d423847b8e2e9872' and md5(to_jsonb(t)::text)='53a6fd7307105fa89c34f6dcd85dcc9b')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_df0f0d60fa767a43d423847b8e2e9872';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{features}',$text_ae23ed56aa8fbde8$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, tus pasos no harán ruido, independientemente de la superficie que pises. También tendrás ventaja en las pruebas de Destreza (Sigilo) que requieran moverse sin hacer ruido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_ae23ed56aa8fbde8$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_df0f0d60fa767a43d423847b8e2e9872';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_f0437da48a839a9472a94e2e679a9f94' and md5(to_jsonb(t)::text)='2fd141ba99db7c03c3d2a672b390a553')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_f0437da48a839a9472a94e2e679a9f94';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_628909b16073e6e5$[{"id":"itf_27c79e0ad8db3a51e69d6511e43b8c52","kind":"action","name":"Hoja Fásica","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Hoja Fásica","expression":"1d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.","showInActions":true},{"id":"phase-blade","kind":"other","name":"Hoja Fásica · Stix","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"1d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"shadow-step","kind":"bonus-action","name":"Salto entre Sombras","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nTeletransporte hasta 15 pies a espacio desocupado visible, sin ataques de oportunidad; una vez por descanso corto o largo.\n\nDuración: Instantánea.\n\nAlcance: 15 pies.\n\nCoste: 1 salto.","showInActions":true}]$text_628909b16073e6e5$::jsonb,true),'{rules,personalDescription}',$text_7d0ad9435aca71d9$"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."$text_7d0ad9435aca71d9$::jsonb,true),'{catalog,revision}',$text_b17ef6d19c7a5b1e$16$text_b17ef6d19c7a5b1e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_f0437da48a839a9472a94e2e679a9f94';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and content_key='imported:monster:legacy:1f706ea5cb33f5940fe687b5' and md5(to_jsonb(t)::text)='683b6eb92c3f67fda5ac03ec4c23446d')then raise exception 'ITEM_TEXT_CONFLICT:merchant:imported:monster:legacy:1f706ea5cb33f5940fe687b5';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{inventory,0,description}',$text_383ecff6579ff2c0$"Objeto · Precio base · Peso\nAbrojos (bolsa de 20) · 1 po · 2 lb\n\nAbrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_383ecff6579ff2c0$::jsonb,true),'{inventory,0,features}',$text_816adba2fd0e635e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_816adba2fd0e635e$::jsonb,true),'{inventory,0,rules,definition,description}',$text_ad9e1c5eb1c88758$[{"id":"official-table","rows":[["Abrojos (bolsa de 20)","1 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_ad9e1c5eb1c88758$::jsonb,true),'{inventory,0,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,0,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,0,rules,definition,capabilities}')cap),true),'{inventory,1,description}',$text_b941c3ef7d1ae2c4$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nAlabarda feroz · 20 po (solo objeto mundano base; no es el precio de la variante mágica) · 6 lb · 1d10 cortante · Pesada, Gran alcance, A dos manos · +0\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_b941c3ef7d1ae2c4$::jsonb,true),'{inventory,1,features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{inventory,1,rules,definition,description}',$text_c07bdca3cc773c73$[{"id":"official-table","rows":[["Alabarda feroz","20 po (solo objeto mundano base; no es el precio de la variante mágica)","6 lb","1d10 cortante","Pesada, Gran alcance, A dos manos","+0"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_c07bdca3cc773c73$::jsonb,true),'{inventory,1,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,1,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6851a11da4c0ecd0$["official-table","vicious-2014"]$text_6851a11da4c0ecd0$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,1,rules,definition,capabilities}')cap),true),'{inventory,2,description}',$text_2afaad17ec2660fa$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nDardo de cerbatana · 1 po · 1 lb · 50 · 0.02 · 2\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_2afaad17ec2660fa$::jsonb,true),'{inventory,2,rules,definition,description}',$text_ba2dd7539bfe43ab$[{"id":"official-table","rows":[["Dardo de cerbatana","1 po","1 lb","50","0.02","2"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_ba2dd7539bfe43ab$::jsonb,true),'{inventory,2,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,2,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,2,rules,definition,capabilities}')cap),true),'{inventory,4,features}',$text_33444504bb0c5fb3$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás utilizar una acción para pronunciar su palabra de activación e invocar a un determinado djinn del Plano Elemental del Aire. El djinn aparecerá en un espacio sin ocupar que elijas a 36 m o menos de ti. Permanecerá mientras te concentres (como si te concentraras en un conjuro) hasta un máximo de 1 hora o hasta que sus puntos de golpe se reduzcan a 0. A continuación, regresará a su plano.\n\nMientras esté invocado, el djinn será amistoso contigo y tus compañeros. Obedecerá cualquier orden que le des, utilices el idioma que utilices. Si no le das ninguna, el djinn se defenderá de los atacantes, pero no llevará a cabo ninguna otra acción.\n\nUna vez que se haya ido, no se podrá volver a invocarlo durante 24 horas. El anillo se volverá no mágico si el djinn muere.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_33444504bb0c5fb3$::jsonb,true),'{inventory,4,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,5,description}',$text_f74e82d3c7405be2$"Objeto · Precio base · Peso\nÁbaco · 2 po · 2 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f74e82d3c7405be2$::jsonb,true),'{inventory,5,rules,definition,description}',$text_89f2a195eae4b3f6$[{"id":"official-table","rows":[["Ábaco","2 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_89f2a195eae4b3f6$::jsonb,true),'{inventory,5,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,5,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,5,rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and content_key='imported:monster:legacy:1f706ea5cb33f5940fe687b5';

